// بيقرر لكل إشعار: يحفظه بقائمة الإشعارات، يبعته لأجهزتك، ويبعت تنبيه واتساب إذا هيك اخترت
const S = {};
for (const it of $('Read Settings N').all()) { const r = it.json; if (r.key) S[String(r.key).trim()] = r.value; }
const num = (v, d) => { const n = Number(v); return (v === '' || v === null || v === undefined || isNaN(n)) ? d : n; };
const stamp = $now.setZone('__TIMEZONE__').toFormat('yyyy-MM-dd HH:mm:ss');
const kinds = new Set(String(S.notify_kinds ?? 'msg,lead,camp,tpl,server').split(',').map(x => x.trim()).filter(Boolean));
const sd = $getWorkflowStaticData('global'); sd.t = sd.t || {};
const nowMs = Date.now();
for (const k of Object.keys(sd.t)) if (nowMs - sd.t[k] > 2 * 86400000) delete sd.t[k];
const notes = $('Notify In').all().map(i => i.json).filter(n => n && n.title);
const subs = $('Read Push N').all().map(i => i.json).filter(p => /^https:\/\//.test(String(p.endpoint || '')) && String(p.dead || '') !== '1');
// تنبيه واتساب: تلقائي = بس إذا ما في جهاز مشغّل عليه الإشعارات
const mode = String(S.alert_whatsapp || 'auto').trim();
const waOn = mode === 'on' || (mode === 'auto' && !subs.length);
const tpl = String(S.alert_template || '').trim(), pid = String(S.phone_number_id || '').trim();
const nums = String(S.alert_numbers || '').split(/[,\s]+/).map(x => x.replace(/\D/g, '')).filter(x => x.length >= 10);
const waUrl = `https://graph.facebook.com/${String(S.api_version || 'v23.0').trim()}/${pid}/messages`;
const thr = num(S.alert_throttle_min, 20) * 60000;
const out = [];
let push = false;
for (const n of notes) {
  if (!n.force && !kinds.has(String(n.kind || ''))) continue;
  out.push({ json: { route: 'note', at: stamp, kind: String(n.kind || ''), title: String(n.title).slice(0, 120), body: String(n.body || '').slice(0, 300), link: String(n.link || '') } });
  const key = String(n.key || '');
  if (!key || n.force || nowMs - (sd.t['p:' + key] || 0) > 20000) { push = true; if (key) sd.t['p:' + key] = nowMs; }
  if (!waOn || !tpl || !pid || !nums.length || !n.wa_text || n.self) continue;
  if (n.throttle && key && nowMs - (sd.t['w:' + key] || 0) < thr) continue; // رسائل عادية: تنبيه واحد لنفس الشخص كل فترة
  if (key) sd.t['w:' + key] = nowMs;
  const panel = /^https:\/\//.test(String(S.panel_url || '')) ? String(S.panel_url).trim() : '__N8N_URL__/webhook/wac';
  const link = String(n.link || '') ? ` · ${String(n.link).startsWith('chat=') ? 'افتح المحادثة ورد من البرنامج' : 'افتح البرنامج'}: ${panel}#${n.link}` : ` · افتح البرنامج: ${panel}`;
  const txt = (String(n.wa_text).replace(/[\n\t]+/g, ' ').replace(/ {4,}/g, '   ').slice(0, 900 - link.length) + link);
  for (const to of nums) out.push({ json: { route: 'wa', url: waUrl, payload: { messaging_product: 'whatsapp', to, type: 'template',
    template: { name: tpl, language: { code: String(S.alert_language || 'ar').trim() }, components: [{ type: 'body', parameters: [{ type: 'text', text: txt }] }] } } } });
}
// إشعار للأجهزة (بدون محتوى: الجهاز بيسحب آخر إشعار من البرنامج)
const pem = String(S.vapid_private || ''), pub = String(S.vapid_public || '').trim();
if (push && subs.length && pem.includes('PRIVATE KEY') && pub) {
  const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
  const b64u = str => { const b = Array.from(str, ch => ch.charCodeAt(0) & 255); let s = '', i = 0;
    for (; i + 2 < b.length; i += 3) { const v = (b[i] << 16) | (b[i + 1] << 8) | b[i + 2]; s += A[v >> 18 & 63] + A[v >> 12 & 63] + A[v >> 6 & 63] + A[v & 63]; }
    if (b.length - i === 1) { const v = b[i] << 16; s += A[v >> 18 & 63] + A[v >> 12 & 63]; }
    else if (b.length - i === 2) { const v = (b[i] << 16) | (b[i + 1] << 8); s += A[v >> 18 & 63] + A[v >> 12 & 63] + A[v >> 6 & 63]; }
    return s; };
  const exp = Math.floor(nowMs / 1000) + 12 * 3600;
  const subj = /^(https:\/\/|mailto:)/.test(String(S.vapid_sub || '')) ? String(S.vapid_sub) : '__N8N_URL__';
  for (const p of subs) {
    const m = String(p.endpoint).match(/^(https:\/\/[^/]+)/);
    if (!m) continue;
    const unsigned = b64u(JSON.stringify({ typ: 'JWT', alg: 'ES256' })) + '.' + b64u(JSON.stringify({ aud: m[1], exp, sub: subj }));
    out.push({ json: { route: 'push', endpoint: String(p.endpoint), unsigned, pem, pub } });
  }
}
return out;

// تحويل التوقيع لصيغة JWT (ES256) وتجهيز طلب الإشعار
const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
const B = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const fromB64 = s => { const o = []; let buf = 0, bits = 0; for (const ch of String(s).replace(/[^A-Za-z0-9+/]/g, '')) { buf = ((buf << 6) | B.indexOf(ch)) & 0xffffff; bits += 6; if (bits >= 8) { bits -= 8; o.push((buf >> bits) & 255); } } return o; };
const b64u = b => { let s = '', i = 0;
  for (; i + 2 < b.length; i += 3) { const v = (b[i] << 16) | (b[i + 1] << 8) | b[i + 2]; s += A[v >> 18 & 63] + A[v >> 12 & 63] + A[v >> 6 & 63] + A[v & 63]; }
  if (b.length - i === 1) { const v = b[i] << 16; s += A[v >> 18 & 63] + A[v >> 12 & 63]; }
  else if (b.length - i === 2) { const v = (b[i] << 16) | (b[i + 1] << 8); s += A[v >> 18 & 63] + A[v >> 12 & 63] + A[v >> 6 & 63]; }
  return s; };
// DER: 30 len 02 rlen r 02 slen s  →  r||s (32 بايت لكل وحدة)
const fix = x => { while (x.length > 32 && x[0] === 0) x = x.slice(1); while (x.length < 32) x = [0].concat(x); return x; };
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const d = fromB64(j.sig || '');
  let i = 2; if (d[1] & 0x80) i = 2 + (d[1] & 0x7f);
  if (d[0] !== 0x30 || d[i] !== 0x02) continue;
  const rl = d[i + 1], r = d.slice(i + 2, i + 2 + rl); i = i + 2 + rl;
  if (d[i] !== 0x02) continue;
  const sl = d[i + 1], s = d.slice(i + 2, i + 2 + sl);
  const jwt = j.unsigned + '.' + b64u(fix(r).concat(fix(s)));
  out.push({ json: { endpoint: j.endpoint, auth: `vapid t=${jwt}, k=${j.pub}` } });
}
return out;

// نتيجة الإشعار لكل جهاز: إذا الجهاز لغى الاشتراك (404/410) بنشطبه
const src = $('Push Req').all();
const stamp = $now.setZone('__TIMEZONE__').toFormat('yyyy-MM-dd HH:mm:ss');
return $input.all().map((it, i) => {
  const r = it.json || {};
  const code = Number(r.statusCode || (r.error && (r.error.status || r.error.httpCode)) || 0);
  return { json: { endpoint: String(((src[i] || {}).json || {}).endpoint || ''), dead: [404, 410].includes(code) ? '1' : '', last_code: String(code || 'err'), last_at: stamp } };
}).filter(x => x.json.endpoint);
